INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-01','Reading Max Ratings: Absolute Maximum','Easy','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A transistor datasheet lists V_CEO(max) = 40 V as absolute maximum rating. A designer applies 38 V collector-emitter voltage. This is:','{"choices": ["Safe — 38 V is within the 40 V limit", "Safe only at temperatures below 25°C", "Unsafe — absolute maximum ratings must never be exceeded AND should not be operated near them; only a 2 V margin is insufficient for production", "Unsafe because the part is wrong for this application"], "correct": 0}'::jsonb,'38 V is technically within the absolute maximum rating. However, best practice is to derate to 80% of max (32 V here). Absolute maximum ratings define stress levels, not operating conditions. Operating right at the limit reduces reliability and MTBF.','{multiple_choice}'::text[],0.75) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-02','Op-Amp Input Offset Voltage','Easy','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','An op-amp datasheet specifies V_OS (input offset voltage) = 5 mV typical, 15 mV maximum. In a unity-gain buffer circuit, what is the worst-case DC output error?','{"choices": ["5 mV", "75 mV", "15 mV", "0 mV"], "correct": 2}'::jsonb,'In a unity-gain buffer (gain = 1), the output error = V_OS × gain = 15 mV × 1 = 15 mV. For high-gain circuits, output error = V_OS × closed-loop gain, so offset matters more in precision, high-gain designs.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-03','MOSFET Gate Threshold Voltage','Easy','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A logic-level MOSFET datasheet shows V_GS(th) = 1.0 V (min) to 3.0 V (max). A 3.3 V logic signal drives the gate. Will the MOSFET turn fully ON?','{"choices": ["Yes, always — 3.3 V exceeds V_th max", "No, it won''t turn on", "Not guaranteed — V_GS = 3.3 V may not fully enhance the MOSFET if V_th = 3.0 V; R_DS(on) will be higher than specified", "Only at temperatures above 50°C"], "correct": 2}'::jsonb,'At V_GS = 3.3 V and V_th = 3.0 V (worst case), V_GS − V_th = only 0.3 V — insufficient for full enhancement. R_DS(on) specs are typically guaranteed at V_GS = 4.5 V or 10 V. Use a 5 V gate drive or a true logic-level MOSFET.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-04','Understanding Timing Diagrams: Setup Time','Easy','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A flip-flop datasheet specifies setup time t_su = 5 ns and hold time t_h = 2 ns relative to the clock edge. Data must be stable for at least:','{"choices": ["5 ns after the clock edge", "5 ns before and 2 ns after the clock edge — a total window of 7 ns", "2 ns total", "7 ns before the clock edge"], "correct": 1}'::jsonb,'Setup time (t_su): data must be stable at least 5 ns BEFORE the active clock edge. Hold time (t_h): data must remain stable at least 2 ns AFTER the clock edge. Violating either causes metastability.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-05','BJT h_FE Parameter','Easy','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A BJT datasheet lists h_FE (DC current gain β) = 100 minimum, 300 typical. A designer calculates base current for I_C = 100 mA using the typical value. What is the risk?','{"choices": ["No risk — typical is always accurate", "The base current will always be too high", "In production, devices with h_FE near 100 (minimum) will not saturate — always design for minimum h_FE, not typical", "Typical values are never valid at high current"], "correct": 2}'::jsonb,'h_FE varies by 3:1 or more across production lots. Designing with typical values means some devices (at minimum h_FE) won''t receive enough base drive. Always use minimum h_FE for saturation/ON-state calculations.','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-06','Quiescent Current vs Supply Voltage','Medium','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A microcontroller datasheet shows two graphs: active current at 16 MHz = 8 mA @ 3.3 V, sleep current = 1 µA. The MCU runs 1% active, 99% sleep. Average current ≈:','{"choices": ["8 mA", "81.99 µA", "4 mA", "400 µA"], "correct": 1}'::jsonb,'I_avg = 0.01 × 8 mA + 0.99 × 1 µA = 80 µA + 0.99 µA ≈ 81 µA. This is why duty-cycle power analysis from datasheet graphs is critical for battery life estimation in IoT devices.','{multiple_choice}'::text[],0.74) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-07','SPI Interface Electrical Parameters','Medium','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','An SPI peripheral datasheet specifies: V_IH(min) = 0.7 × VCC, V_IL(max) = 0.3 × VCC. The sensor operates at 3.3 V; master GPIO operates at 5 V. V_OH of master = 4.9 V. Is level translation needed?','{"choices": ["No — both are logic-compatible", "Yes — 4.9 V from master exceeds sensor''s absolute maximum VCC + 0.3 V; direct connection risks damaging the sensor", "No — CMOS inputs are always 5 V tolerant", "Level translation only needed for clock signals"], "correct": 1}'::jsonb,'Most 3.3 V devices are NOT 5 V tolerant on I/O pins. Applying 4.9 V to a 3.3 V input can damage input protection diodes. Always check the absolute maximum rating for V_I and the note on "5 V tolerant" pins explicitly.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-08','Thermal Resistance: Junction Temperature','Medium','ECE','arena','calculate','Datasheet Intelligence','multiple_choice','A power MOSFET has θ_JA = 50°C/W (junction-to-ambient). At 25°C ambient, the device dissipates 2 W. What is the junction temperature?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-09','Decoupling Capacitor Selection','Medium','ECE','arena','select','Datasheet Intelligence','multiple_choice','An IC datasheet states "bypass each VCC pin with 100 nF ceramic capacitor, located within 1 mm of pin." Why specify both value AND placement?','{"choices": ["Placement is irrelevant — only capacitance value matters", "Both value and placement matter: 100 nF handles switching transients at >1 MHz; placement minimises PCB trace inductance which would otherwise reduce effectiveness at high frequencies", "Only placement matters, not the capacitance value", "Ceramic capacitors are only needed for analog ICs"], "correct": 1}'::jsonb,'Every millimetre of PCB trace adds ~1 nH inductance. At 100 MHz, 5 nH has impedance 3.1 Ω — defeating a 100 nF cap (impedance ~0.016 Ω). Close placement is mandatory for effective HF bypassing.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-10','Propagation Delay in Logic ICs','Medium','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A 74HC00 NAND gate datasheet shows: t_pHL = 7 ns (max), t_pLH = 7 ns (max) at 5 V, 25°C. In a 5-gate serial chain, worst-case propagation delay ≈:','{"choices": ["7 ns", "1.4 ns", "35 ns", "14 ns"], "correct": 2}'::jsonb,'Worst-case: 5 gates × 7 ns/gate = 35 ns. This cumulative delay limits maximum operating frequency. For a 10 MHz clock period (100 ns), 35 ns is 35% of the period — borderline for reliable operation.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-11','Op-Amp GBP and Phase Margin','Medium','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','An op-amp datasheet shows GBP = 10 MHz and phase margin = 45° in unity-gain configuration. If used with gain = 10, what is the −3 dB bandwidth and is stability a concern?','{"choices": ["1 MHz, stability is fine", "10 MHz, stability may be an issue", "100 kHz, check phase margin for gain-of-10 configuration", "1 MHz, stability may be an issue"], "correct": 0}'::jsonb,'BW = GBP/gain = 10 MHz/10 = 1 MHz. At gain > 1, the loop gain drops faster, and phase margin typically improves. Phase margin concern is greatest at unity gain (minimum phase margin). 45° at unity gain is adequate but not comfortable.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-12','I²C Pull-Up Resistor Calculation','Medium','ECE','arena','calculate','Datasheet Intelligence','multiple_choice','An I²C bus operates at 3.3 V, 400 kHz (Fast mode). Bus capacitance C_b = 100 pF. The I²C spec requires rise time t_r < 300 ns. Minimum pull-up resistor:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-13','ESD Rating: HBM Model','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A component datasheet rates ESD at ±2000 V HBM (Human Body Model). A technician handles the component without an ESD wrist strap. The human body can generate 1000–30000 V. Is this dangerous?','{"choices": ["No — ±2000 V HBM is very robust", "No — ESD only damages old NMOS technology", "Yes — unprotected handling can easily exceed 2000 V; damage may be latent (not immediately obvious) and can cause field failures", "Only at humidity below 20%"], "correct": 2}'::jsonb,'HBM 2000 V means the IC can survive the HBM pulse of a human body at 2 kV; real handling can reach 10–30 kV. Latent ESD damage (partial oxide damage) causes gradual failure — ICs pass immediate test but fail in the field. ESD procedures are mandatory.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-14','PSRR: Power Supply Rejection Ratio','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','An op-amp datasheet shows PSRR = 80 dB at DC, falling to 20 dB at 1 MHz. A 100 mV peak power-supply ripple at 1 MHz is present. What output ripple noise does this cause?','{"choices": ["0.1 mV", "10 mV", "100 mV", "1 µV"], "correct": 1}'::jsonb,'At 1 MHz, PSRR = 20 dB → ratio = 10. Ripple referred to output = 100 mV / 10 = 10 mV. Op-amps have much lower PSRR at high frequencies — supply decoupling near the IC is critical for AC ripple rejection.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-15','Oscillator Datasheet: Aging and Stability','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A TCXO datasheet specifies: frequency stability ±1 ppm (−40°C to +85°C), aging ±0.5 ppm/year. For a 10 MHz clock used in a 5-year deployment, worst-case total frequency error is:','{"choices": ["1 ppm", "±1 ppm", "±3.5 ppm", "±6 ppm"], "correct": 2}'::jsonb,'Temperature stability: ±1 ppm. Aging over 5 years: ±0.5 ppm/year × 5 = ±2.5 ppm. Total worst-case: ±(1 + 2.5) = ±3.5 ppm. For a 10 MHz clock: ±35 Hz. GPS disciplining can correct aging in precise applications.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-16','ADC Datasheet: ENOB vs Ideal Resolution','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A 12-bit ADC datasheet states ENOB = 10.5 bits (effective number of bits). What does this mean for measurement accuracy?','{"choices": ["The ADC provides 12-bit accuracy always", "The ADC has noise and distortion equivalent to a 10.5-bit ideal ADC — the other 1.5 bits are degraded by noise", "ENOB only matters for audio applications", "12-bit and 10.5 ENOB are equivalent"], "correct": 1}'::jsonb,'ENOB = (SINAD − 1.76) / 6.02. A 12-bit ADC with ENOB = 10.5 means actual noise+distortion reduces dynamic range to 10.5 effective bits. The "lost" 1.5 bits represent quantisation noise floor elevation from circuit non-idealities.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-17','Power Derating Curve','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A transistor is rated P_D = 2 W at 25°C, with a derating factor of 16 mW/°C. Maximum dissipation at 85°C ambient is:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-18','Common Mode Voltage Range','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A differential amplifier datasheet specifies common mode input range (CMIR) = −1 V to V+ − 2 V (where V+ = 5 V supply). An input signal of +4.5 V common-mode is applied. What happens?','{"choices": ["The circuit works normally", "The CMIR is exceeded (4.5 V > 3 V limit); amplifier output will clip or behave unpredictably", "The gain doubles", "The circuit switches to single-ended mode"], "correct": 1}'::jsonb,'CMIR limit = V+ − 2 = 5 − 2 = 3 V. Applying 4.5 V common-mode exceeds this. The input stage saturates. Many op-amps have different CMIR from their output swing — always check both. Rail-to-rail input ICs are needed for V_cm near supply rails.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-19','Crystal Load Capacitance Matching','Hard','ECE','arena','select','Datasheet Intelligence','multiple_choice','A crystal is specified for 12 MHz ± 30 ppm with load capacitance C_L = 18 pF. The oscillator circuit PCB provides C_stray = 3 pF. What external capacitors (C1, C2 to GND) should be used?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-20','Interpreting Min/Typ/Max Columns','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A datasheet shows a parameter with Min=–, Typ=10 mA, Max=15 mA. A design engineer uses the typical value of 10 mA for current budgeting. This is:','{"choices": ["Correct — typical is the guaranteed value", "Incorrect — the Min is blank (not tested or specified); only Max = 15 mA is guaranteed; always budget for maximum current", "Correct only for prototypes", "Incorrect — typical values are not valid without Min specification"], "correct": 1}'::jsonb,'When Min is "—", it means no lower bound is tested or guaranteed. Only the maximum is guaranteed. For power supply sizing, always use worst-case (maximum) values. Typical values come from characterisation, not production test.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-21','UART Framing: Baud Rate Tolerance','Hard','ECE','arena','calculate','Datasheet Intelligence','multiple_choice','UART standard allows ±2.5% clock mismatch between transmitter and receiver. A transmitter at 115200 baud has 0.5% error (+576 baud). The receiver has 1.5% error. Are they compatible?','{"choices": ["Yes — total error = 2% < 2.5%", "No — individual errors must each be < 1.25%", "Yes always, as long as data rate matches", "Cannot determine without knowing word length"], "correct": 0}'::jsonb,'Total cumulative error = 0.5 + 1.5 = 2%, which is within the ±2.5% UART tolerance window. Errors add in the worst case when both drift in opposite directions. However, 2% leaves minimal margin for a 10-bit frame (1 start + 8 data + 1 stop).','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-22','Package Parasitic Inductance','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','A SMD inductor datasheet shows self-resonant frequency (SRF) = 100 MHz for a 100 nH inductor. Above the SRF, the component behaves as:','{"choices": ["A pure inductor", "A capacitor (the parasitic shunt capacitance dominates)", "A short circuit", "A pure resistor"], "correct": 1}'::jsonb,'At SRF, inductive and capacitive parasitics resonate. Above SRF, the distributed capacitance dominates and the component is capacitive. Never use inductors above their SRF — choose an inductor with SRF >> your operating frequency.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-23','MOSFET Safe Operating Area (SOA)','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','An SOA curve on a MOSFET datasheet shows a boundary on the I_D vs V_DS graph. The boundary at high V_DS drops with a −1 slope on log-log scale. What does this region represent?','{"choices": ["Thermal limit (constant power P = V_DS × I_D = constant)", "Gate oxide breakdown", "On-state resistance limit", "Package current limit"], "correct": 0}'::jsonb,'The −1 slope on log-log I_D vs V_DS means I_D ∝ 1/V_DS → P = V×I = constant: this is the thermal limit (constant power hyperbola). The SOA boundary also includes: RDS(on) limit (low V_DS), package current limit (horizontal), and secondary breakdown (steep drop).','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-24','Noise Density: Op-Amp Voltage Noise','Hard','ECE','arena','calculate','Datasheet Intelligence','multiple_choice','An op-amp has voltage noise density e_n = 5 nV/√Hz. For a 100 kHz bandwidth, what is the RMS output noise (referred to input)?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-di-25','LDO Regulator: Dropout Voltage','Hard','ECE','arena','interpret','Datasheet Intelligence','multiple_choice','An LDO regulator outputs 3.3 V with V_dropout = 200 mV at 500 mA. The input voltage is 3.4 V. The device draws 600 mA (including a transient). What happens?','{"choices": ["Output stays at 3.3 V", "The output drops below 3.3 V — headroom (3.4 − 3.3 = 0.1 V) is less than minimum dropout (0.2 V) at that current", "The LDO enters current limiting", "The LDO shuts down for overcurrent"], "correct": 1}'::jsonb,'V_in − V_out = 0.1 V < V_dropout = 0.2 V. The LDO cannot regulate; output tracks input (V_out ≈ V_in − V_sat). This is "dropout." Always ensure V_in ≥ V_out + V_dropout(max) at maximum load current.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
